window.ScripturaLexicons.BDAG_PART_0213 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-01\" data-source=\"BDAG\" data-search=\"κυνάριον, ου, τό substantivo neutro; diminutivo cachorrinho; cão doméstico; cão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυνάριον, ου, τό</td><td>substantivo neutro; diminutivo</td><td>cachorrinho; cão doméstico; cão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-02\" data-source=\"BDAG\" data-search=\"κυνηγέσιον, ου, τό substantivo neutro caça de animais; espetáculo de caça BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυνηγέσιον, ου, τό</td><td>substantivo neutro</td><td>caça de animais; espetáculo de caça</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-03\" data-source=\"BDAG\" data-search=\"κυνηγέω verbo caçar; perseguir; capturar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυνηγέω</td><td>verbo</td><td>caçar; perseguir; capturar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-04\" data-source=\"BDAG\" data-search=\"κυνηγία substantivo feminino caça; talvez desfile de animais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυνηγία</td><td>substantivo feminino</td><td>caça; talvez desfile de animais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-05\" data-source=\"BDAG\" data-search=\"κυνήγιον, ου, τό substantivo neutro caça de feras; combate com animais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυνήγιον, ου, τό</td><td>substantivo neutro</td><td>caça de feras; combate com animais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-06\" data-source=\"BDAG\" data-search=\"κυοφορέω verbo estar grávida; gerar; conceber; frutificar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυοφορέω</td><td>verbo</td><td>estar grávida; gerar; conceber; frutificar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-07\" data-source=\"BDAG\" data-search=\"Κύπριος, ου, ὁ substantivo masculino; gentílico cipriota; habitante de Chipre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κύπριος, ου, ὁ</td><td>substantivo masculino; gentílico</td><td>cipriota; habitante de Chipre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-08\" data-source=\"BDAG\" data-search=\"Κύπρος, ου, ἡ nome próprio feminino; topônimo Chipre; ilha mediterrânea BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κύπρος, ου, ἡ</td><td>nome próprio feminino; topônimo</td><td>Chipre; ilha mediterrânea</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-09\" data-source=\"BDAG\" data-search=\"κύπτω verbo inclinar-se; abaixar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κύπτω</td><td>verbo</td><td>inclinar-se; abaixar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-10\" data-source=\"BDAG\" data-search=\"Κυρεῖνος nome próprio masculino; variante Quirino; veja Κυρήνιος BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κυρεῖνος</td><td>nome próprio masculino; variante</td><td>Quirino; veja Κυρήνιος</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-11\" data-source=\"BDAG\" data-search=\"Κυρηναῖος, ου, ὁ substantivo masculino; gentílico cireneu; natural de Cirene BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κυρηναῖος, ου, ὁ</td><td>substantivo masculino; gentílico</td><td>cireneu; natural de Cirene</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-12\" data-source=\"BDAG\" data-search=\"Κυρήνη, ης, ἡ nome próprio feminino; topônimo Cirene; capital da Cirenaica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κυρήνη, ης, ἡ</td><td>nome próprio feminino; topônimo</td><td>Cirene; capital da Cirenaica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-13\" data-source=\"BDAG\" data-search=\"Κυρήνιος nome próprio masculino Quirino; governador romano da Síria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Κυρήνιος</td><td>nome próprio masculino</td><td>Quirino; governador romano da Síria</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-14\" data-source=\"BDAG\" data-search=\"κυρία, ας, ἡ substantivo feminino senhora; patroa; comunidade figurada como senhora BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυρία, ας, ἡ</td><td>substantivo feminino</td><td>senhora; patroa; comunidade figurada como senhora</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-15\" data-source=\"BDAG\" data-search=\"κυριακός, ή, όν adjetivo pertencente ao Senhor; do Senhor; dominical BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυριακός, ή, όν</td><td>adjetivo</td><td>pertencente ao Senhor; do Senhor; dominical</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-16\" data-source=\"BDAG\" data-search=\"κυριεύω verbo exercer domínio; governar; dominar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυριεύω</td><td>verbo</td><td>exercer domínio; governar; dominar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-17\" data-source=\"BDAG\" data-search=\"κύριος, ία, ιον adjetivo principal; essencial; autoritativo; válido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κύριος, ία, ιον</td><td>adjetivo</td><td>principal; essencial; autoritativo; válido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-18\" data-source=\"BDAG\" data-search=\"κύριος, ου, ὁ substantivo masculino proprietário; senhor; amo; Senhor Deus; Senhor Jesus; título honorífico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κύριος, ου, ὁ</td><td>substantivo masculino</td><td>proprietário; senhor; amo; Senhor Deus; Senhor Jesus; título honorífico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-19\" data-source=\"BDAG\" data-search=\"κυριότης, ητος, ἡ substantivo feminino natureza senhorial; senhorio; domínio; potestade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυριότης, ητος, ἡ</td><td>substantivo feminino</td><td>natureza senhorial; senhorio; domínio; potestade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0213-20\" data-source=\"BDAG\" data-search=\"κυρόω verbo ratificar; validar; decidir; confirmar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κυρόω</td><td>verbo</td><td>ratificar; validar; decidir; confirmar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0213-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυνάριον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro; diminutivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυνάριον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (Theopomp. Com. [V a.C.] 90; Pla., Euthyd. 298d; X., Cyr. 8, 4, 20; Epict. 4, 1, 111; IEph II, 506, 4; PGM 4, 2945; 2947; 2951. Rejeitado por Phryn. p. 180 Lob. em favor de <span class=\"greek\">κυνίδιον</span>): diminutivo de <span class=\"greek\">κύων</span>; cão doméstico ou de colo, em contraste com o cão da rua ou da fazenda (veja B-D-F §111, 3; Mlt-H. 346f), mas empregado também sem qualquer força diminutiva (Plut., Arat. 7, 3); cachorrinho, cão, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:26f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 7:27f</a> (Eutecnius 1 p. 17, 11f, cães domésticos que comem as sobras da <span class=\"greek\">τράπεζα</span>; compare Ael. Dion., <span class=\"greek\">α</span>, 159: <span class=\"greek\">ψωμὸς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ̔ν</span> <span class=\"greek\">ἐκματτόμενοι</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">χεῖρας</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δεῖπνον</span> <span class=\"greek\">ἐρρίπτουν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">κυσίν</span>. Semelhantemente Paus. Attic., <span class=\"greek\">α</span>, 134). AConnolly em New Docs 4, 157–59.—DELG s.v. <span class=\"greek\">κύων</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυνηγέσιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυνηγέσιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja os dois verbetes seguintes; Eur., Hdt. e outros): caça de animais (geralmente no plural, como, por exemplo, OGI 529, 14; CIG 2511), promovida em determinados dias festivos por certos magistrados, por exemplo, em Esmirna, pelos asiarcas. MPol 12:2. B. 190.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυνηγέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυνηγέω</span> (veja o verbete anterior e os dois seguintes; forma posterior de <span class=\"greek\">κυνηγετέω</span>): particípio do 1º aoristo, plural, <span class=\"greek\">κυνηγήσαντες</span>, Just.; aoristo passivo <span class=\"greek\">ἐκυνηγήθην</span>: caçar (Pla., Aristot.; Gen 25:27; Jos., Bell. 1, 496; Just., D. 104, 1; Sb 6319, 47 [I a.C.]; papiros, por exemplo PSI 901, 13; 22 [46 d.C.]); <span class=\"greek\">πῶς</span> <span class=\"greek\">ἐκυνηγήθης</span>;, como foste capturado?, AcPl Ha 5, 3.—DELG s.v. <span class=\"greek\">ἄγω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυνηγία</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυνηγία</span> (veja o verbete anterior e também o seguinte; autores trágicos, Aristot., Polyb. e outros; PTebt 339, 9): caça, talvez em sentido transferido exibição de animais, procissão de animais: <span class=\"greek\">ἐποίε̣ι̣</span> <span class=\"greek\">ὁ̣</span> <span class=\"greek\">Ἱερώνυμος</span> <span class=\"greek\">κυν</span>[<span class=\"greek\">ηγίαν</span>], AcPl Ha 1, 33 (o sentido ‘desfile de animais’ para essa restauração pode ser inferido do contexto, mas uma restauração alternativa <span class=\"greek\">κυν</span>[<span class=\"greek\">ήγιον</span>] [veja o próximo verbete], ‘caça de feras’ [latim venatio], é igualmente provável. O autor dispunha do termo <span class=\"greek\">πόμπη</span>, habitualmente empregado para procissões solenes, caso pretendesse destacar esse aspecto [quanto aos termos <span class=\"greek\">πόμπη</span> e <span class=\"greek\">πομπεύω</span>, veja AcPlTh: Aa I 255, 5 e 11; 256, 5]).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυνήγιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυνήγιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (veja o verbete precedente; forma posterior de <span class=\"greek\">κυνηγέσιον</span>, ‘caça de feras’; em diversas acepções desde Polyb.; também Sir 13:19 [‘presa’]): no plural <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span>., caça de feras em que seres humanos lutam por sua vida contra animais, AcPl Ha 3, 5.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυοφορέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυοφορέω</span> (<span class=\"greek\">κύος</span> [=<span class=\"greek\">κύημα</span>], ‘embrião, feto’, + <span class=\"greek\">φορέω</span>, ‘carregar [por tempo prolongado]’; veja também <span class=\"greek\">κύω</span>; Hippocr. e outros; M. Ant. 9, 3, 2; Eccl 11:5; Philo, Sacr. Abel. 102 e frequentemente; Just., D. 33, 4): estar grávida; metaforicamente, ser fecundo: <span class=\"greek\">γῆ</span> <span class=\"greek\">κυοφοροῦσα</span>, a terra fértil, 1 Cl 20:4 (compare Philo, Opif. Mundi 43). Na passiva, ser concebido (Artem. 4, 84; Galen XIX p. 174 K.), de Jesus: <span class=\"greek\">ἐκυοφορήθη</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">Μαρίας</span>, foi concebido por Maria, IEph 18:2. <span class=\"greek\">τὸν</span> <span class=\"greek\">προφητικὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">ὸ̔ς</span> <span class=\"greek\">ἐ</span>[<span class=\"greek\">κ</span>]<span class=\"greek\">υοφορήθη</span> … <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">αὐτῆς</span>, AcPl Ha 8, 27f=BMM recto 36.—DELG s.v. <span class=\"greek\">κυέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κύπριος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κύπριος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Pind., Hdt. e outros; inscrições; 2 Macc 4:29; Joseph.; Tat. 41, 1): cipriota, habitante de Chipre: <span class=\"greek\">Μνάσων</span> <span class=\"greek\">τις</span> <span class=\"greek\">Κ</span>., certo Mnasom, cipriota, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:16</a>; <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">Κ</span>., homens cipriotas, 11:20; <span class=\"greek\">Κ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">γένει</span>, cipriota de nascimento, 4:36.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κύπρος, ου, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino; topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κύπρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; inscrições; 1 Macc 15:23; 2 Macc 10:13; Philo, Leg. ad Gai. 282; Joseph., SibOr; Tat. 9:3): Chipre, ilha situada no golfo formado pela costa meridional da Ásia Menor e a costa síria. Desde 22 a.C., era província senatorial governada por procônsul (<span class=\"greek\">ἀνθύπατος</span>, veja essa entrada). Visitada por Paulo em sua chamada primeira viagem missionária, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:4</a>. O cristianismo, contudo, já havia sido levado à ilha por fugitivos de Jerusalém, 11:19. Compare ainda 15:39; 21:3; 27:4.—WEngel, Kypros 1841; AMurray-ASmith-HWalters, Excavations in Cyprus 1900; EOberhummer, D. Insel Cypren 1903; Pauly-W. XII 1924, 59–117; Baedeker 363ff; Ramsay, Bearing 150ff; EPower, Dict. de la Bible, Suppl. II ’34, 1–23; Kl.-Pauly III 404ff; RGunnis, Historic Cyprus ’36–’56; GHill, A History of Cyprus, 4 vols. ’48–’52; TMitford, em ANRW II/7/2 ’80, 1298–1308.—OEANE II 89–96. ABD I 1228–30.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κύπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κύπτω</span>: 1º aoristo <span class=\"greek\">ἔκυψα</span>; inclinar-se para baixo (assim Hom. e outros; LXX; En 14:25; JosAs 18:7), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:7</a>. <span class=\"greek\">κάτω</span> <span class=\"greek\">κ</span>., curvar-se até o chão (Aristoph., Vesp. 279; Theophr., Char. 24, 8; Chariton 2, 3, 6; 2, 5, 5; Pel.-Leg. 23, 18), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:6</a>, 8, variante de leitura; AcPl Ha 4, 12.—M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κυρεῖνος</h1><div class=\"entry-meta\"><span>nome próprio masculino; variante</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κυρεῖνος</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:2</a>, variante de leitura; veja <span class=\"greek\">Κυρήνιος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κυρηναῖος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino; gentílico</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κυρηναῖος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (veja o próximo verbete; Hdt. e outros; OGI 767, 31; Michel 897, 26; PPetr I, 16 [1], 3; 22 [1], 3; 2 Macc 2:23; Joseph.): cireneu (veja <span class=\"greek\">Κυρήνη</span>), com artigo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:1</a> (Socrates, Ep. 28, 1 <span class=\"greek\">Θεόδωρος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Κ</span>.; Athen. 7, 14 p. 281c). Sem artigo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 23:26</a> (Diod S 11, 84, 1 <span class=\"greek\">Πολύμναστος</span> <span class=\"greek\">Κυρηναῖος</span>).—Como adjetivo: <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">Κ</span>., homem cireneu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:32</a>; <span class=\"greek\">ἄνδρες</span> <span class=\"greek\">Κ</span>., homens cireneus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:20</a>. Em Jerusalém, os judeus de Cirene tinham uma sinagoga, só para si ou juntamente com outros judeus da diáspora, 6:9 (Schürer II 428; III 60f).—BZimolong, BZ 21, ’33, 184–88; EBishop, ET 51, ’39/40, 148–53; WBarclay, ET 72, ’60, 28–31.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κυρήνη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino; topônimo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κυρήνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (veja o próximo verbete; Pind., Hdt. e outros; inscrições; 1 Macc 15:23; Jos., Bell. 7, 437–46, Ant. 14, 114–18; SibOr 5, 198): Cirene, capital da região de Cirenaica (Pentápole), no norte da África; desde 27 a.C., a Cirenaica estava unida a Creta como província senatorial governada por procônsul. Cirene era antiga colônia grega, onde se estabeleceram numerosos judeus (Schürer III 60f). <span class=\"greek\">τὰ</span> <span class=\"greek\">μέρη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Λιβύης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">Κυρήνην</span>, as regiões da Líbia próximas de Cirene, isto é, a Líbia Cirenaica, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:10</a>.—LMalten, Kyrene 1911; estudos italianos: RivFil, n.s. 6, fasc. 2; 3, 1928; UvWilamowitz, Kyrene 1928; PRomanellis, La Cirenaica Romana ’43; EKirsten, Nordafrikanische Stadtbilder ’61, 39ff; Pauly-W. XII, 156ff; Kl.-Pauly III 410ff; BHHW II, 1034; PECS 253–55; OEANE II 97f.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Κυρήνιος</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Κυρήνιος</span> (veja o verbete precedente; IG III/1, 599 [=IG II2, 4143] <span class=\"greek\">Μᾶρκον</span> <span class=\"greek\">Κυρήνιον</span>; ARoos, Mnemos. 9, ’41, 306–18), mais corretamente <span class=\"greek\">Κυρίνιος</span> (B-D-F §41; Mlt-H. 72), <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, grafia encontrada também em certos manuscritos: Quirino (P. Sulpicius. Compare Jos., Bell. 2, 433; 7, 253, Ant. 17, 355; 18, 1; 26; 29; 20, 102; Just.), governador imperial da Síria, mencionado no NT em relação ao recenseamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:2</a>.—A seu respeito, veja a bibliografia sob <span class=\"greek\">ἀπογραφή</span> e <span class=\"greek\">ἡγεμονεύω</span>, bem como FSpitta, ZNW 7, 1906, 290–303; WWeber, ibid. 10, 1909, 307–19; Ramsay, Bearing 275–300, JRS 7, 1917, 273ff; WLodder, D. Schätzung des Qu. bei Fl. Josephus 1930; GOgg, ET 79, ’68, 231–36; Schürer I 399–427; Boffo, Iscrizioni no. 23 (bibliografia: p. 182f); Pauly-W. IV A 1, 822ff; BHHW III 1536ff.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυρία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυρία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (forma feminina do adjetivo substantivado <span class=\"greek\">κύριος</span> [veja essa entrada I]. Raro e tardio como nome próprio: Preisigke, Namenbuch 188; HBeyer-HLietzmann, D. jüd. Katakombe der Villa Torlonia ’31, inscrição 41).</p>\n<p class=\"entry-text\">① Mulher de posição especial; senhora, patroa: <span class=\"greek\">ἡ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἔργου</span>, a responsável pelo serviço doméstico, provavelmente aquela que distribui as tarefas da casa (compare Tob. 2:12, a respeito de ‘empregadores’), GJs 2:2. Usado ao dirigir-se a pessoa determinada (Plut., Mor. 271d; Epict., Ench. 40; Cass. Dio 48, 44; POxy 112, 1; 3; 7; 744, 2=Ltzm., Griech. Papyri2 1910, 7; carta em Dssm., LO 160 [LAE2 193, n. 6]; <span class=\"greek\">κ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">μήτηρ</span>, minha senhora mãe, TestAbr A 3 p. 79, 25 [Stone p. 6].—A LXX usa <span class=\"greek\">κ</span>. para designar a senhora em oposição à escrava; assim também JosAs; Philo, Congr. Erud. Gr. 154; Jos., Ant. 17, 137; 139; PTebt 413, 1; 6; 20), Hv 1, 1, 5; 1, 2, 2; 1, 3, 3; 1, 4, 2; 2, 1, 3; 3, 1, 3; 8; 3, 2, 4; 3, 3, 1; 4f; 3, 4, 1; 3; 3, 5, 3; 3, 6, 5f; 3, 8, 2; 5f; 4, 2, 2f; 4, 3, 1. Muitos entendem <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2JN.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2J 1</a>; 5 nesse sentido literal (por exemplo, BWestcott, The Epistles of St. John 1886, 214; HPoggel, D. 2. u. 3. Brief d. Apostels Joh. 1896, 127ff). Sobre o sentido menos formal ‘querida’, encontrado nos papiros, veja M-M. s.v.</p>\n<p class=\"entry-text\">② Outros estudiosos consideram mais provável que <span class=\"greek\">κ</span>. seja aqui figurado, referindo-se aos cristãos como grupo: congregação (veja <span class=\"greek\">ἀδελφή</span> 2b); <span class=\"greek\">ἐκλεκτὴ</span> <span class=\"greek\">κυρία</span> costuma ser traduzido por ‘senhora escolhida’ (ou ‘eleita’) (assim BWeiss e outros; veja BBresky, Das Verhältnis des zweiten Johannesbriefs zum dritten 1906, 2ff; FDölger, Ac V/3, ’36, 211–17, Domina mater ecclesia u. d. ‘Herrin’ im 2 J; ABrooke, ICC; RBultmann, comentário Hermeneia. Sobre a precariedade da remissão ao Lex. Cantabr. [p. 79f, com nota na p. 119f, Houtsma; também Demetr. of Phaleron: 228 Fgm. 4 p. 961], veja H-JKlauck, ZNW 81, ’90, 135–42). Para a imagem do povo de Deus como mulher, veja Jer 4:31; 38:21; Zeph 3:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:25f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:13</a>. A proposta (HGibbins, Exp. 6th ser., 6, 1902, 228f) de fazer de <span class=\"greek\">ἐκλεκτή</span> um nome próprio e de <span class=\"greek\">κυρία</span> um adjetivo tem pouco a recomendá-la.—DELG s.v. <span class=\"greek\">κύριος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυριακός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυριακός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">κύριος</span>): relativo ao que pertence ao Senhor, do Senhor (frequente em inscrições [desde 68 d.C.: OGI 669, 13; 18] e papiros com o sentido ‘imperial’ em certas expressões: tesouro imperial, serviço imperial etc. Veja Dssm., NB 44ff [BS 217ff], LO 304ff [LAE2 362ff]; Hatch 138f; e <span class=\"greek\">πρῶτος</span> 1a<span class=\"greek\">α</span>, final; Iren. 1, 8, 1 [Harv. I 67, 1; 6f]): <span class=\"greek\">κ</span>. <span class=\"greek\">δεῖπνον</span>, Ceia do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:20</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμέρα</span>, dia do Senhor (Kephal. I 192, 1; 193, 31; <span class=\"greek\">ὁ</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">τέλειος</span> … <span class=\"greek\">ἀεὶ</span> <span class=\"greek\">ἄγει</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμέρας</span>, Orig., C. Cels. 8, 22, 6), isto é, certamente domingo (assim em grego moderno; compare POxy 3407 [IV d.C.]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:10</a> (WStott, NTS 12, ’65, 70–75). Para isso, <span class=\"greek\">κυριακὴ</span> <span class=\"greek\">κυρίου</span>, D 14:1. Sem <span class=\"greek\">κυρίου</span> (Kephal. I 194, 9; 195, 6; Did., Gen. 190, 2), GPt 9:35; 12:50. <span class=\"greek\">τῷ</span> <span class=\"greek\">σαββάτῳ</span> <span class=\"greek\">ἐπερχομένης</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κ</span>., quando o dia do Senhor se aproxima no sábado, AcPl Ha 3, 9. <span class=\"greek\">κατὰ</span> <span class=\"greek\">κυριακὴν</span> <span class=\"greek\">ζῆν</span>, observar o dia do Senhor (em oposição a <span class=\"greek\">σαββατίζειν</span>), IMg 9:1 (sobre a omissão de <span class=\"greek\">ἡμέρα</span>, compare Jer 52:12 <span class=\"greek\">δεκάτῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">μηνός</span> e veja <span class=\"greek\">ἀγοραῖος</span> 2). <span class=\"greek\">σύνταξιν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κυριακῶν</span> <span class=\"greek\">ποιούμενος</span> <span class=\"greek\">λογίων</span>, fazendo uma exposição ordenada dos ditos do Senhor, Papias (2:15) (veja também <span class=\"greek\">ἐξήγησις</span>, final); <span class=\"greek\">κ</span>. <span class=\"greek\">λογίων</span> (11:1; 12:2); <span class=\"greek\">κ</span>. <span class=\"greek\">λόγων</span> (3:1); <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξηγήσεων</span> (8:9).—SMcCasland, The Origin of the Lord’s Day: JBL 49, 1930, 65–82; JBoehmer, D. christl. Sonntag nach Urspr. u. Gesch. ’31; PCotton, From Sabbath to Sunday ’33; WRordorf, Der Sonntag … im ältesten Christentum ’62 (tradução inglesa AGraham ’68); HRiesenfeld, Sabbat et Jour du Seigneur: TWManson memorial vol. ’59, 210–17.—B. 1008. DELG s.v. <span class=\"greek\">κύριος</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυριεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυριεύω</span> (veja <span class=\"greek\">κύριος</span>): futuro <span class=\"greek\">κυριεύσω</span>; 1º aoristo <span class=\"greek\">ἐκυρίευσα</span>; perfeito, 1ª pessoa do plural, <span class=\"greek\">κεκυριεύκαμεν</span>; aoristo passivo, subjuntivo <span class=\"greek\">κυριευθῇ</span>, TestJud 21:4; particípio <span class=\"greek\">κυριευθείς</span>, TestAsh 1:8 (desde X.): genericamente, ‘ser senhor ou amo de’.</p>\n<p class=\"entry-text\">① Exercer autoridade ou ter controle; governar, acerca de pessoas, com genitivo daquilo sobre o que se exerce autoridade ou controle (X., Mem. 2, 6, 22; Polyb. 4, 18, 2; OGI 229, 56 [III a.C.]; Gen 3:16; 37:8; En 22:14; TestJos 3:2; ApcMos 24:25; Iren. 1, 25, 3 [Harv. I 206, 11]; Jos., Bell. 1, 39; Just.): <span class=\"greek\">οἱ</span> <span class=\"greek\">βασιλεῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐθνῶν</span> <span class=\"greek\">κυριεύουσιν</span> <span class=\"greek\">αὐτῶν</span>, os reis das nações dominam sobre elas, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:25</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:16</a>, variante de leitura. <span class=\"greek\">θλιβέντα</span> <span class=\"greek\">κυριεῦσαι</span> <span class=\"greek\">αὐτοῦ</span>, obtê-lo por meio do sofrimento, B 7:11. <span class=\"greek\">ἐντολῆς</span> <span class=\"greek\">κ</span>., dominar um mandamento, isto é, apropriar-se dele, Hm 5, 2, 8. <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεώς</span> <span class=\"greek\">τινος</span>, dominar a fé de alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:24</a>.—Sobre Deus (Theod. Da 4:25, 32; 5:21; En 22:14; EpArist 45; 269 <span class=\"greek\">δόξης</span> <span class=\"greek\">πάσης</span>; PGM 1, 214 <span class=\"greek\">ὁ</span> <span class=\"greek\">κυριεύων</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">ἀγγέλων</span>; 12, 115 <span class=\"greek\">ὁ</span> <span class=\"greek\">κυριεύων</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">κόσμου</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">κυριεύων</span>, aquele que domina sobre todas as coisas, Hs 9, 23, 4; <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">παντὸς</span> <span class=\"greek\">κόσμου</span> <span class=\"greek\">κυριεύων</span>, aquele que governa o mundo inteiro, B 21:5. Sobre Cristo: <span class=\"greek\">νεκρῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ζώντων</span> <span class=\"greek\">κ</span>., Senhor de mortos e vivos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:9</a>.—Absolutamente (En 103:12 <span class=\"greek\">οἳ</span> <span class=\"greek\">κυριεύουσιν</span>; Orig., C. Cels. 8, 4, 16; <span class=\"greek\">τὸ</span> <span class=\"greek\">κυριεύειν</span> Did., Gen. 113, 15), B 6:18; <span class=\"greek\">οἱ</span> <span class=\"greek\">κυριεύοντες</span>, os senhores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:15</a>.</p>\n<p class=\"entry-text\">② Ser senhor de, dominar, acerca de coisas que assumem controle sobre uma pessoa; sentido transferido de 1 e igualmente com genitivo (Sextus 41; 363a; Philo, Leg. All. 3, 187 <span class=\"greek\">πάθος</span>; TestSim 3:2, Iss 7:7): da lei, <span class=\"greek\">κυριεύει</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀνθρώπου</span>, domina o ser humano, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:1</a> (JDerrett, Law in the NT, ’70, 461–71); do pecado, 6:14; da morte, v. 9.—B. 1319. DELG s.v. <span class=\"greek\">κύριος</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κύριος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">I. <span class=\"greek\">κύριος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span> (Pind. e outros; inscrições, papiros): comparativo <span class=\"greek\">κυριώτερος</span> (Just., A II, 13, 3); superlativo <span class=\"greek\">κυριώτατος</span> (Just., D. 11, 2); advérbio <span class=\"greek\">κυρίως</span>. A acepção primária diz respeito à posse de poder ou autoridade em diversos sentidos: ‘forte, autoritativo, válido, governante’; em seguida, àquilo que tem importância superior: principal, essencial (Aeschyl. e outros; 4 Macc 1:19; Jos., Ant. 20, 41, C. Ap. 1, 19; 2, 177; Just.; Ath. 22:2): <span class=\"greek\">τὸ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">κυριώτερον</span>, mas o que é mais importante, IMg 1:2 (compare Diog. L. 4, 26 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>, de maneira perfeitamente definida).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κύριος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">II. <span class=\"greek\">κύριος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (forma masculina do adjetivo substantivado <span class=\"greek\">κύριος</span> [veja I], desde Aeschyl.; Appian, Bell. Civ. 4, 92 §385 [=<span class=\"greek\">ὁ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κῦρος</span> <span class=\"greek\">ἔχων</span>]; inscrições, papiros, LXX, pseudoepígrafos; Philo, Joseph., apologistas; empréstimo no hebraico rabínico. Para a correspondente forma feminina, veja <span class=\"greek\">κυρία</span>): genericamente, ‘senhor, amo’.</p>\n<p class=\"entry-text\">① Aquele que está no comando em virtude da posse; proprietário (X., Symp. 6, 1; Diod S 4, 15, 3; 14, 7, 6; inscrições, papiros, LXX): <span class=\"greek\">κ</span>. <span class=\"greek\">πάντων</span>, senhor de tudo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 4:1</a> (Diod S 33, 7, 1; Philostrat., Vi. Apoll. 1, 13 p. 12, 10, de quem atingiu a maioridade e controla os próprios bens).</p>\n<p class=\"entry-text\">ⓐ De coisas, com objeto impessoal: <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀμπελῶνος</span>, proprietário da vinha (compare SIG 742, 6 <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">χώρας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:8</a>; 21:40; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:13</a>, 15; <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">οἰκίας</span>, senhor da casa (Ex 22:7; SIG 1215, 28; PTebt 5, 147 [118 a.C.] <span class=\"greek\">τοὺς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">οἰκιῶν</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:35</a>. De um <span class=\"greek\">πῶλος</span>, potro: <span class=\"greek\">οἱ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτοῦ</span>, seus proprietários (PHib 34, 3, uma parelha de bois; Ex 21:29 [<span class=\"greek\">αὐτοῦ</span>=<span class=\"greek\">τοῦ</span> <span class=\"greek\">ταύρου</span>]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:33</a> (ASouter, Exp. 8th ser., 8, 1914, 94f, em ligação com o plural nessa passagem e em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:16</a>, 19, entende os proprietários como marido e esposa; o plural <span class=\"greek\">οἱ</span> <span class=\"greek\">κύριοι</span> tem esse sentido em Diod S 34 + 35, Fgm. 2, 10 e 2, 37: casal proprietário de escravos. Por outro lado, na coleção de fábulas de Esopo de Syntipas 16 p. 534 P., <span class=\"greek\">οἱ</span> <span class=\"greek\">κύριοι</span> de um cão designa vários metalúrgicos. Sobre o pano de fundo hebraico para o possível entendimento do plural em sentido singular, ‘proprietário’, veja RButh, JBL 104, ’86, 680–85). A acepção ‘proprietário’ facilmente passa a senhor, amo, aquele que tem completo controle de alguma coisa (Diod S 5, 42, 5 <span class=\"greek\">θανάτου</span> <span class=\"greek\">κύριοι</span>, senhores sobre a vida e a morte; 10, 17, 1 e 2 <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>, senhor do próprio corpo; Ptolem., Apotel. 3, 11, 10 <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>; PsSol 2:29 <span class=\"greek\">κ</span>. <span class=\"greek\">γῆς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θαλάσσης</span>; Philo, Spec. Leg. 3, 67; Jos., C. Ap. 2, 200): <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">θερισμοῦ</span>, o Senhor da colheita (Jos., Ant.4, 227 <span class=\"greek\">κύριος</span> <span class=\"greek\">ἔστω</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">φυτὰ</span> <span class=\"greek\">καρποῦσθαι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:2</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σαββάτου</span>, Senhor do sábado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:5</a>.</p>\n<p class=\"entry-text\">ⓑ Com objeto pessoal: em oposição a <span class=\"greek\">δοῦλος</span>, escravo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.16\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:16</a>; seguido de genitivo de pessoa (compare Judg 19:11; Gen 24:36; TestSol 22:5; TestJob 7:9; TestGad 4:4; JosAs 4:14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:24f</a>; 18:31f; 24:48; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:36</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">δούλου</span>, o senhor do escravo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:46</a>. Uso absoluto, embora o sentido seja inequívoco (Diod S 8, 5, 3; ApcEsdr 3:14 p. 27, 27f Tdf.), 12:37, 42b; 14:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:15</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:4a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:9a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:1</a>. Vários senhores do mesmo escravo (Billerb. I 430.—TestJos 14:2): <span class=\"greek\">δυσὶν</span> <span class=\"greek\">κυρίοις</span> <span class=\"greek\">δουλεύειν</span>, servir a dois senhores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:16</a>, 19 (veja Souter sob ⓐ acima). <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> define mais precisamente o âmbito em que vigora a relação de serviço: <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">σάρκα</span> <span class=\"greek\">κ</span>., senhores segundo a carne, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:22</a>. Como forma de tratamento empregada por escravos: <span class=\"greek\">κύριε</span>, senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:27</a>; 25:20, 22, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:8</a>; 14:22; 19:16, 18, 20, 25.</p>\n<p class=\"entry-text\">② Alguém que ocupa posição de autoridade; senhor, amo.</p>\n<p class=\"entry-text\">ⓐ De seres terrenos, designação de pessoa de elevada posição: do marido, em contraste com a esposa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:6</a> (Gen 18:12; TestAbr A 15 p. 95, 15 [Stone p. 38]; ApcMos 2; compare Plut., De Virt. Mul. 15 p. 252b; SIG 1189, 7; 1190, 5; 1234, 1); de pai, dito por seu filho, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:29</a> (compare BGU 423, 2 <span class=\"greek\">Ἀπίων</span> <span class=\"greek\">Ἐπιμάχῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κυρίῳ</span>; 818, 1; 28; Gen 31:35; dito por filha, TestJob 46:2; JosAs 4:5); de funcionário em alta posição, pelas pessoas que se relacionam com ele (compare PFay 106, 15; 129, 1; 134, 2; BGU 648, 16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:63</a>. Como forma de dirigir-se a pessoa respeitada em geral, equivalente a ‘senhor’ (como no grego moderno), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:21</a>; 20:15 (mas veja NWyatt, ZNW 81, ’90, 38); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:30</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:14</a> (compare Epict. 3, 23, 11; 19; Gen 23:6; 44:18; TestAbr A 2 p. 78, 33 [Stone p. 4]; JosAs 7:8 e outros). A concepção greco-romana peculiar dos governantes ‘divinizados’ é examinada sob 2b<span class=\"greek\">β</span>.</p>\n<p class=\"entry-text\">ⓑ De seres transcendentes. <span class=\"greek\">α</span>. Como designação de Deus (quanto a esse costume, cujas raízes estão no Oriente, veja as referências em Ltzm., Hdb. excursus sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:9</a>; Bousset, Kyrios Christos2 1921, 95–98; Dssm., LO 298f [LAE 353ff]; veja também SEG XXXVI, 350 e inscrições adicionais citadas por DZeller, DDD 918f; LXX [onde frequentemente substitui o nome Yahweh no texto massorético]; pseudoepígrafos; Philo, Just.; Hippol. Ref. 8, 17, 1; Orig., C. Cels. 1, 35, 6.—FDoppler, D. Wort ‘Herr’ als Göttername im Griech.: Opusc. philol. v. kath. akad. Philologenverein in Wien I 1926, 42–47; MParca, ASP 31, ’91, 51 [bibliografia]): <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:6</a>, 9, 28, 46; 2:15, 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:26</a> (Ps 2:2); 7:33; 8:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:7</a> (talvez referente a Cristo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:16</a>, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:7</a>; 4:15. Sem o artigo (sobre presença ou omissão do artigo, veja BWeiss [<span class=\"greek\">θεός</span>, início]; B-D-F §254, 1; Mlt-Turner 174), à maneira de nome próprio (<span class=\"greek\">οὐδένα</span> <span class=\"greek\">κύριον</span> <span class=\"greek\">ὀνομνάζουσι</span> <span class=\"greek\">πλὴν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>, Hippol. Ref. 9, 26, 2): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:17</a>, 58; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.49\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:21</a> (Ps 109:4); 12:6 (Pr 3:12); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 5</a> (<span class=\"greek\">θεὸς</span> <span class=\"greek\">Χριστός</span> P72); 9. <span class=\"greek\">ἄγγελος</span> <span class=\"greek\">κυρίου</span>, anjo do Senhor (LXX, TestSol, GrBar e outros), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:20</a>, 24; 2:13, 19; 28:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:11</a>; 2:9a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:3</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:19</a>; 7:30, variante de leitura; 8:26; 12:7, 23. <span class=\"greek\">δόξα</span> <span class=\"greek\">κυρίου</span>, glória do Senhor (Is 40:5; PsSol 5:19; 7:31; TestLevi 8:11; ApcMos 37), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:9b</a>; <span class=\"greek\">δούλη</span> <span class=\"greek\">κ</span>., serva do Senhor, 1:38; <span class=\"greek\">ἡμέρα</span> <span class=\"greek\">κ</span>., dia do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:20</a> (Jo 3:4); <span class=\"greek\">νόμος</span> <span class=\"greek\">κ</span>., lei do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:23f</a>, 39; <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">κ</span>., nome do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:9</a> (Ps 117:26; PsSol 6:1 e outros); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:21</a> (Jo 3:5); <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">κ</span>., Espírito do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:18</a> (Is 61:1); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.39\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:39</a>; <span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">κ</span>., palavra do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:25</a> (Gen 15:1 e outros); <span class=\"greek\">φωνὴ</span> <span class=\"greek\">κ</span>., voz do Senhor (Gen 3:8 e outros); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:31</a>; <span class=\"greek\">χεὶρ</span> <span class=\"greek\">κ</span>., mão do Senhor (Ex 9:3 e outros; TestJob 26:4; ApcMos prólogo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.66\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:66</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">κυρίου</span>, o ungido do Senhor, 2:26 (PsSol 17:32 [<span class=\"greek\">Χριστὸς</span> <span class=\"greek\">κύριος</span>, veja aparato]).—Com o âmbito do domínio mais expressamente definido (Diod S 3, 61, 5, Zeus é <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σύμπαντος</span> <span class=\"greek\">κόσμου</span>; 6 <span class=\"greek\">θεὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">αἰῶνα</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σύμπαντος</span> <span class=\"greek\">κόσμου</span>; Jos., Ant. 20, 90 <span class=\"greek\">τῶν</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">κ</span>.; Just., D. 127, 2 <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">πάντων</span>): <span class=\"greek\">κ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span>, Senhor do céu e da terra (PGM 4, 640f; ParJer 5:32 [Harris]), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:21</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:24</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">κυριευόντων</span>, Senhor dos senhores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:15</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, nosso Senhor, 1:14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:15</a> (LXX; PsSol 10:5). Compare 22:6 (veja Num 16:22; 27:16). <span class=\"greek\">κ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, Senhor Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:8</a>; com <span class=\"greek\">μου</span> (<span class=\"greek\">σου</span> etc.), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:7</a> (Dt 6:16), 10 (Dt 6:13); 22:37 (Dt 6:5); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:29f</a> (Dt 6:4f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:16</a> e outros. <span class=\"greek\">κ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span>, Senhor Deus de Israel, 1:68 (PsSol 16:3; TestSol 1:13). <span class=\"greek\">κ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> (<span class=\"greek\">ἡμῶν</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">παντοκράτωρ</span>, Deus, o Senhor (nosso), o Todo-Poderoso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:8</a>; 15:3; 16:7; 19:6; 21:22 (TestSol D 4:7; compare ParJer 9:6). <span class=\"greek\">κ</span>. <span class=\"greek\">Σαβαώθ</span>, Senhor Sabaote, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:29</a> (Is 1:9; TestSol 1:6 e outros; Just., D. 64, 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:4</a>.—Com preposições: <span class=\"greek\">ἐνώπιον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, diante do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:15</a> (Ex 23:17; 1 Km 1:25 e outros; TestJob 15:6 e outros; TestReub 1:9 e outros). <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span>, da parte do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:11</a> (ambos Ps 117:23). <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίῳ</span>, junto do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:8</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κύριον</span>, para o Senhor, Hs 9, 12, 6 (LXX; PsSol 1:1 e outros).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. Intimamente ligado ao costume de aplicar <span class=\"greek\">κ</span>. às divindades está o de honrar com o mesmo título governantes (divinizados) (exemplos [início de 2b<span class=\"greek\">α</span>] em Ltzm., op. cit.; Bousset 93; Dssm., 299ff [LAE 356]; FKattenbusch, Das apostol. Symbol II 1900, 605ff; KPrümm, Herrscherkult u. NT: Biblica 9, 1928, 3–25; 119–40; 289–301; JFears, RAC XIV, 1047–93; JvanHenten, 1341–52 [bibliografia]; compare a atitude dos lacedemônios: <span class=\"greek\">φοβούμενοι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἕνα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Λυκούργου</span> <span class=\"greek\">νόμον</span>, ‘respeitando seu único senhor, a lei de Licurgo’, Orig., C. Cels. 8, 6, 12). Desde o tempo de Cláudio (POxy. 37, 6; O. Wilck II 1038, 6), encontramos cada vez mais imperadores romanos assim designados, embora em casos isolados até anteriormente (OGI 606, 1; sobre a posição de Augusto, veja DioCass. 51, 7f), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 25:26</a>.—Sobre governantes divinizados em geral, veja LCerfaux-JTondriau, Un concurrent du Christianisme: le culte des souverains dans la civilisation gréco-romaine ’57; FTaeger, Charisma, 2 vols. ’57–60; DRoloff, Göttlichkeit, Vergöttlichung und Erhöhung zu seligem Leben, ’70. Veja em especial a coletânea de artigos e resenhas de diversos estudiosos em Römischer Kaiserkult, organizada por AWlosok ’78.</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">κύριος</span> também é empregado em referência a Jesus.</p>\n<p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">א</span>. Em citações do AT, em que se entende a expressão como referência ao Senhor da nova comunidade: <span class=\"greek\">ἡ</span> <span class=\"greek\">ὁδὸς</span> <span class=\"greek\">κ</span>., o caminho do Senhor (Is 40:3), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:23</a>. <span class=\"greek\">εἶπεν</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">μου</span>, disse o Senhor a meu Senhor (Ps 109:1: o primeiro <span class=\"greek\">κ</span>. é Deus, o segundo é Cristo; veja Billerb. IV 452–65: Der 110. Ps. in d. altrabb. Lit.; <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">χριστὸς</span> <span class=\"greek\">κ</span>. [ou <span class=\"greek\">κυρίου</span>; veja 2b<span class=\"greek\">α</span>], PsSol 17:32), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:44</a> (compare os vv. 43, 45); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a> (compare o v. 37); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:42</a> (compare o v. 44); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:34</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">καυχώμενος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">καυχάσθω</span>, aquele que se gloria, glorie-se no Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:31</a> (compare Jer 9:22f). <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">κυρίου</span>, o nome do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:13</a> (compare Jo 3:5). <span class=\"greek\">σὺ</span> <span class=\"greek\">κατ</span>’ <span class=\"greek\">ἀρχάς</span>, <span class=\"greek\">κύριε</span>, <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ἐθεμελίωσας</span>, tu, Senhor, no princípio fundaste a terra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:10</a> (compare Ps 101:26). <span class=\"greek\">εἰ</span> <span class=\"greek\">ἐγεύσασθε</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">χρηστὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>, se provastes que o Senhor é bondoso, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:3</a> (compare Ps 33:9). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:15</a> acrescenta <span class=\"greek\">Χριστόν</span> a <span class=\"greek\">κύριον</span> <span class=\"greek\">ἁγιάσατε</span>, Is 8:13.</p>\n<p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ב</span>. Fora das citações do AT, Mt e Mk chamam Jesus de <span class=\"greek\">κύριος</span> em apenas uma passagem (palavras do próprio Jesus), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:3</a>=<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:3</a> (mas veja RBratcher, ET 64, ’52/53, 93; New Docs 1, 43; JDerrett, NovT 13, ’71, 241–58, sobre o sistema de transporte público; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:31</a>, 34); contudo, registram que ele era tratado por ‘Senhor’ (<span class=\"greek\">κύριε</span>), uma vez em Mk (7:28) e mais frequentemente em Mt, por exemplo 8:2, 6, 8, 21, 25; 9:28; 14:28, 30; 15:22, 25, 27; 16:22 (também ApcSed 12:2).—Lk se refere a Jesus muito mais frequentemente como <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. (Iren. 1, prólogo 2 [Harv. I 4, 5] e 5, 26, 2 [Harv. II 396, 2]): 7:13; 10:1, 39 (<span class=\"greek\">Ἰησοῦ</span> P75; <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰησοῦ</span> P45 e outros), 41; 11:39; 12:42a; 13:15; 17:5f; 18:6; 19:8 e outros. O vocativo <span class=\"greek\">κύριε</span> também ocorre frequentemente: 5:8, 12; 9:54, 61; 10:17, 40; 11:1; 12:41 e outros.—Em J, a designação <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. é rara; nos primeiros 19 capítulos, somente em passagens textualmente incertas (4:1, variante de leitura; 6:23, com omissão em alguns manuscritos) ou suspeitas por outros motivos (11:2); depois 20:2, 18, 20, 25; compare os vv. 13, 28; 21:7ab, 12. Por outro lado, <span class=\"greek\">κύριε</span>, como forma de tratamento, é extraordinariamente comum em todo o livro: 4:11, 15, 19, 49; 5:7; 6:34, 68 e outros (mais de 30 ocorrências).—No final longo de Mk ocorre duas vezes a designação <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., 16:19, 20. Em GPt, <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. ocorre em 1:2; 2:3ab; 3:6, 8; 4:10; 5:19; 6:21, 24; 12:50ab; 14:59, 60 (na última passagem sem artigo); o fragmento preservado dificilmente oferece oportunidade para o uso do vocativo. 2 Cl introduz ditos apócrifos de Jesus com <span class=\"greek\">λέγει</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., diz o Senhor, 5:2; <span class=\"greek\">λ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">εὐαγγελίῳ</span>, diz o Senhor no Evangelho, 8:5.—A repetição <span class=\"greek\">κύριε</span>, <span class=\"greek\">κύριε</span>, Senhor, Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:21f</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:46</a>; 2 Cl 4:2 (TestAbr A 9 p. 86, 26 [Stone p. 20]; ApcMos 25 p. 14, 1 Tdf.; veja KKöhler, StKr 88, 1915, 471–90).</p>\n<p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ג</span>. Mesmo nas passagens já mencionadas, o uso da palavra <span class=\"greek\">κ</span>. eleva Jesus acima do nível humano (Mani também é <span class=\"greek\">κ</span>. para seus seguidores: Kephal. I 183, 11; 13; 16); essa tendência torna-se ainda mais nítida nas passagens seguintes: <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριος</span>, o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:14</a>; 9:10f, 42; 11:23f; 22:10b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:11</a>; 14:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:13f</a>, 17; 7:10, 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:6</a>, 8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:15b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:7f</a>; B 5:5; IEph 10:3; AcPl Ha 6, 21; 7, 5; 27; 8, 2; AcPlCor 1:6, 14.—Sem artigo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:4</a>; 7:22b; 10:21ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:15a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:24</a>; AcPlCor 1:8. Assim, especialmente nas combinações com preposições: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κυρίου</span>, da parte do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:24</a>. <span class=\"greek\">κατὰ</span> <span class=\"greek\">κύριον</span>, segundo o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:17</a>. <span class=\"greek\">παρὰ</span> <span class=\"greek\">κυρίου</span>, da parte do Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:8</a>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">κύριον</span>, para o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:16</a>; AcPl Ha 6, 9. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κ</span>., para o Senhor, 8, 23. <span class=\"greek\">σὺν</span> <span class=\"greek\">κυρίῳ</span>, com o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:17b</a>. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κυρίου</span>, pelo Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:25b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:13</a>. Especialmente frequente é a fórmula paulina <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>, no Senhor (bibliografia sob <span class=\"greek\">ἐν</span> 4c), que fora das cartas de Paulo aparece apenas em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:13</a>; IPol 8:3; AcPl Ha 3, 23; AcPlCor 1:1, 16 (compare Pol 1:1 <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χριστῷ</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 16</a>; <span class=\"greek\">πιστὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., fiel no Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:21</a>; Hm 4, 1, 4; <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., luz no Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:8</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">σφραγίς</span> <span class=\"greek\">μου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀποστολῆς</span> <span class=\"greek\">ὑμεῖς</span> <span class=\"greek\">ἐστε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., vós sois no Senhor o selo do meu apostolado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:2</a>. Com verbos: <span class=\"greek\">ἀσπάζεσθαι</span>, saudar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:22</a> (GBahr, CBQ 28, ’66, 465f, traduz: a serviço de meu senhor, isto é, Paulo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 16:19</a>. <span class=\"greek\">ἐνδυναμοῦσθαι</span>, fortalecer-se, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.10\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:10</a>. <span class=\"greek\">καλεῖσθαι</span>, ser chamado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:22a</a>. <span class=\"greek\">καυχᾶσθαι</span>, gloriar-se, 1:31. <span class=\"greek\">κοπιᾶν</span>, trabalhar arduamente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:12ab</a>; <span class=\"greek\">μαρτύρεσθαι</span>, testemunhar, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:17</a>. <span class=\"greek\">παραλαμβάνειν</span> <span class=\"greek\">διακονίαν</span>, receber um ministério, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:17</a>. <span class=\"greek\">πεποιθέναι</span> <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span>, confiar em alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:10</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, quanto a alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:4</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:14</a>; 2:24. <span class=\"greek\">προί̈στασθαι</span>, presidir, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:12</a>. <span class=\"greek\">προσδέχεσθαι</span>, acolher, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:29</a>. <span class=\"greek\">στήκειν</span>, permanecer firme, 4:1; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:8</a>. <span class=\"greek\">ὑπακούειν</span>, obedecer, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">αὐτὸ</span> <span class=\"greek\">φρονεῖν</span>, ter o mesmo pensamento, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:2</a>. <span class=\"greek\">θύρας</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ἀνεῳγμένης</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κ</span>., uma porta aberta para mim no Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:12</a>.—Com <span class=\"greek\">διδάσκαλος</span>, mestre, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:13f</a>. Com <span class=\"greek\">σωτήρ</span>, Salvador, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:2</a>; compare 1:11; 2:20 (Just., D. 39, 2). Com <span class=\"greek\">Χριστός</span>, Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:36</a>; compare <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">κύριος</span> (La 4:20; PsSol 17, 32, variante de leitura [GBeale, Christos Kyrios in PsSol 17:32—‘The Lord’s Anointed’ Reconsidered: NTS 31, ’85, 620–27]; PsSol 18, inscrição), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:11</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Χριστός</span>, o Senhor Cristo, AcPlCor 2:3. São especialmente frequentes as fórmulas <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰησοῦς</span>, o Senhor Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:21</a>; 4:33; 8:16; 11:20; 15:11; 16:31; 19:5, 13, 17; 20:24, 35; 21:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:23</a>; 16:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:14</a>; 11:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:17</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:15</a>; 4:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:7</a>; 2:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 5</a>.—<span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">Χριστός</span>, o Senhor Jesus Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:17</a>; 28:31; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 13:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.23\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 4:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHM.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phlm 25</a>; 1 Cl 21:6 (Ar. 15, 1). Sem artigo, sobretudo nos inícios das cartas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:2</a>; 6:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:2</a>; 3:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:2</a>, 12b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:21</a>, variante de leitura; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:1</a>; <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">κ</span>., Cristo Jesus Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:5</a>; <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., Cristo Jesus, o Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:6</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>., Cristo, o Senhor, 2 Cl 9:5. Numa invocação, <span class=\"greek\">κύριε</span> <span class=\"greek\">Ἰησοῦ</span>, Senhor Jesus (compare Sb 8316, 5f <span class=\"greek\">κύριε</span> <span class=\"greek\">Σάραπι</span>; PGM 7, 331 <span class=\"greek\">κύριε</span> <span class=\"greek\">Ἄνουβι</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.59\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:59</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.22.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 22:20</a>. <span class=\"greek\">κύριε</span>, Senhor, AcPl Ha 7:30f, 40.—Com genitivo de pessoa (em muitos lugares, os manuscritos variam consideravelmente na presença ou omissão desse genitivo): <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μου</span>, meu Senhor, ISm 5:2. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, nosso Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:14</a>; IPhld, inscrição; <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦς</span>, nosso Senhor Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 5:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:19</a>; 3:11, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.20\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:20</a>. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, Jesus, nosso Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:1</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Χριστός</span>, nosso Senhor Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:18</a> (única passagem em Paulo sem <span class=\"greek\">Ἰησοῦς</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">Χριστός</span>, nosso Senhor Jesus Cristo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 5:1</a>, 11; 15:6, 30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:2</a>, 7f, 10; 6:11, variante de leitura; 15:57; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:3</a>; 8:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.14\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:14</a>, 18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:3</a>; 5:20; 6:24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:3</a>; 5:9, 23, 28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:1</a>, 14, 16; 3:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:3</a>, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:8</a>, 14, 16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 4</a>, 17, 21 (também TestSol 1:12 D). <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Χριστός</span> <span class=\"greek\">Ἰησοῦς</span>, nosso Senhor Cristo Jesus, AcPlCor 2:5; compare AcPl Ha 8, 17=Ox 1602, 20f//BMM recto 22. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, Jesus Cristo, nosso Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:4</a>; 5:21; 7:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 25</a> (Just., D. 41, 4). (<span class=\"greek\">ὁ</span>) <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἡμῶν</span>, Cristo Jesus, nosso Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:11</a>, variante de leitura, 23; 8:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:2</a>, 12; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:2</a> (<span class=\"greek\">ὁ</span> <span class=\"greek\">ἡμέτερος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span>, Just., D. 32, 3 e 47, 5 e outros). <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μου</span>, Cristo Jesus, meu Senhor, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:8</a>. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">μου</span> <span class=\"greek\">Χριστὸς</span> <span class=\"greek\">Ἰησοῦς</span>, meu Senhor Cristo Jesus, AcPl Ha 7, 29. <span class=\"greek\">ὁ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτῶν</span>, Senhor deles, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:8</a>.—Com outros genitivos: <span class=\"greek\">πάντων</span> <span class=\"greek\">κ</span>., Senhor de todos (compare Pind., I. 5, 53 <span class=\"greek\">Ζεὺς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">κ</span>.; Plut., Mor. 355e, Osíris; PGM 13, 202), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:36</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:12</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">κυρίων</span>, Senhor dos senhores (compare En 9:4), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:14</a>; 19:16.—A confissão da igreja cristã (paulina) é que ‘Jesus é <span class=\"greek\">κύριο</span>’ (talvez ‘nosso <span class=\"greek\">κύριος</span> é Jesus’): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:3</a>; compare 8:6; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:11</a> (sobre esta última passagem, veja <span class=\"greek\">ἁρπαγμός</span> e <span class=\"greek\">κενόω</span> 1. Compare ainda Diod S 5, 72, 1: depois que Zeus foi elevado <span class=\"greek\">ἐκ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">οὐρανόν</span>, da terra ao céu, surgiu nas <span class=\"greek\">ψυχαῖς</span> de todos os que haviam experimentado seus benefícios a convicção <span class=\"greek\">ὡς</span> <span class=\"greek\">ἁπάντων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γινομένων</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">οὗτος</span> <span class=\"greek\">εἴη</span> <span class=\"greek\">κύριος</span>; veja também 3, 61, 6, Zeus aclamado ‘Deus e Senhor’).—Em J a confissão assume a forma <span class=\"greek\">ὁ</span> <span class=\"greek\">κύριός</span> <span class=\"greek\">μου</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span> <span class=\"greek\">μου</span>, meu Senhor e meu Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:28</a> (sobre a combinação de <span class=\"greek\">κύριος</span> e <span class=\"greek\">θεός</span>, veja <span class=\"greek\">θεός</span>, início, e 3c).—JFitzmyer, The Semitic Background of the NT Kyrios-Title: A Wandering Aramaean—Collected Aramaic Essays ’79, 115–42; veja também 87–90.</p>\n<p class=\"entry-text\"><span class=\"greek\">δ</span>. Em certas passagens não está claro se o referente é Deus ou Cristo; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:31</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:19</a>; 7:17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:22b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:16</a> e outros.</p>\n<p class=\"entry-text\"><span class=\"greek\">ε</span>. De outros seres transcendentes. <span class=\"hebrew\" dir=\"rtl\">א</span>. Um anjo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:4</a> (JosAs 14:6 e outros; GrBar 4:1 e outros; ApcZeph), p. 129 Denis.</p>\n<p class=\"entry-text\"><span class=\"hebrew\" dir=\"rtl\">ב</span>. Em contraste com o único <span class=\"greek\">κύριος</span> dos cristãos, há <span class=\"greek\">θεοὶ</span> <span class=\"greek\">πολλοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κύριοι</span> <span class=\"greek\">πολλοί</span>, muitos deuses e muitos senhores, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 8:5</a> (compare Dt 10:17); não podemos dizer exatamente que distinção, se alguma, Paulo faz entre esses <span class=\"greek\">θεοί</span> e <span class=\"greek\">κύριοι</span>; a menos que haja aqui um hendíade, o apóstolo pode sugerir que os <span class=\"greek\">κ</span>. são de categoria inferior aos <span class=\"greek\">θ</span>. (semelhantemente Did., Gen. 248, 5. Sobre os numerosos <span class=\"greek\">θεοί</span> e as divindades inferiores, compare Maximus Tyr. 11, 5ab <span class=\"greek\">θεὸς</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πατήρ</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">θεοὶ</span> <span class=\"greek\">πολλοί</span>, <span class=\"greek\">θεοῦ</span> <span class=\"greek\">παῖδες</span> [= <span class=\"greek\">δαίμονες</span> 11, 12a], <span class=\"greek\">συνάρχοντες</span> <span class=\"greek\">θεοῦ</span>. <span class=\"greek\">Ταῦτα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἕλλην</span> <span class=\"greek\">λέγει</span>, <span class=\"greek\">κ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">βάρβαρος</span>; 8, 8ef. Também Diog. L. 8, 23: o dito de Pitágoras segundo o qual a humanidade deve <span class=\"greek\">τοὺς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">δαιμόνων</span> <span class=\"greek\">προτιμᾶν</span>, honrar os deuses mais do que as divindades ou semideuses <span class=\"greek\">δαίμονες</span>; Heraclitus, Fgm. 5, divide a esfera celestial em <span class=\"greek\">θεοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἥρωες</span>. Veja ainda <span class=\"greek\">κυριότης</span> 3 e, de certa forma, PGM 36, 246 <span class=\"greek\">κύριοι</span> <span class=\"greek\">ἄγγελοι</span>; veja também <span class=\"greek\">θεός</span> 1).—Sobre a palavra em seu conjunto, veja WGraf Baudissin, Kyrios als Gottesname im Judentum u. s. Stelle in d. Religionsgesch., 4 vols. 1926–29; SvenHerner, Die Anwendung d. Wortes <span class=\"greek\">κ</span>. im NT 1903; Dssm., LO 298ff [LAE 353ff]; BBacon, Jesus as Lord: HTR 4, 1911, 204–28; WHeitmüller, ZNW 13, 1912, 333ff; HBöhlig, D. Geisteskultur v. Tarsos 1913, 53ff, Zum Begriff <span class=\"greek\">κύριος</span> bei Pls: ZNW 14, 1913, 23ff, ’<span class=\"greek\">Εν</span> <span class=\"greek\">κυρίῳ</span>: Heinrici Festschr. 1914, 170ff; WBousset, Kyrios Christos2 1921 [tradução inglesa JSteely ’70]; PWern-le, ZTK 25, 1915, 1–92; PAlthaus, NKZ 26, 1915, 439ff; 513ff; Heitmüller, ZTK 25, 1915, 156ff; Bousset, Jesus der Herr 1916; GVos, The Continuity of the Kyrios Title in the NT: PTR 13, 1915, 161–89, The Kyrios Christos Controversy: ibid. 15, 1917, 21–89; EWeber, Zum Gebrauch der <span class=\"greek\">κύριος</span>-Bez.: NKZ 31, 1920, 254ff; ERohde, Gottesglaube u. Kyriosglaube bei Paulus: ZNW 22, 1923, 43ff; RSeeberg, D. Ursprung des Christenglaubens 1914; JWeiss, D. Urchristentum 1917, 351ff; Ltzm., Hdb. excursus sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:9</a>; Burton, ICC Gal 1921, 399–404; WFoerster, Herr ist Jesus 1924; AFrövig, D. Kyriosglaube des NTs 1928; ELohmeyer, Kyr. Jesus 1928; EvDobschütz, <span class=\"greek\">Κύριος</span> <span class=\"greek\">Ἰησοῦς</span>: ZNW 30, ’31, 97–123 (bibliografia); OMichel, D. Christus des Pls: ZNW 32, ’33, 6–31; também 28, 1929, 324–33; Dodd 9–11; LCerfaux, ‘Kyrios’ dans les citations paul. de l’AT: ETL 20, ’43, 5–17; FGrant, An Introd. to NT Thought ’50, 130–37; PÉLangevin, Jésus Seigneur ’67; IPotterie, BRigaux Festschr. ’70, 117–46 (Lucas); JKingsbury, JBL 94, ’75, 246–55 (Mt); FDanker, Luke ’87, 60–81; DZeller, 925–28 (bibliografia).—B. 1330. Schürer II 326. DELG. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυριότης, ητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυριότης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ἡ</span> (Memnon Hist. [I a.C./I d.C.]: 434 Fgm. 1, 4, 6 Jac. <span class=\"greek\">κ</span>. <span class=\"greek\">πολλῶν</span>, ‘domínio sobre muitos’; Achmes 229, 17 <span class=\"greek\">κ</span>. <span class=\"greek\">λαοῦ</span>; Soranus p. 10, 23 <span class=\"greek\">κ</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ζῆν</span>, ‘significado para a vida’; Dositheus 1, 1, da significação especial de uma coisa [com <span class=\"greek\">δύναμις</span>]; escólio a Pla. 111a <span class=\"greek\">κ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀνομάτων</span>, significado das palavras. Em outras passagens nos escritores eclesiásticos e bizantinos e em papiros tardios: PCairMasp 151, 199 [VI d.C.] <span class=\"greek\">παρακαλῶ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">κριτὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">δικαστὴν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κυριότητα</span>; 132 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάσης</span> <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">κ</span>. <span class=\"greek\">ἐξουσίας</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θρόνου</span> <span class=\"greek\">κ</span>. <span class=\"greek\">κυριότητος</span> <span class=\"greek\">ὑφ</span>’ <span class=\"greek\">ἡλίῳ</span>).</p>\n<p class=\"entry-text\">① Natureza essencial de <span class=\"greek\">κύριος</span>, natureza do Senhor, em referência a Deus, D 4:1.</p>\n<p class=\"entry-text\">② Especialmente, poder majestoso exercido pelo <span class=\"greek\">κύριος</span>, poder governante, senhorio, domínio (compare <span class=\"greek\">θειότης</span> como aspecto essencial de <span class=\"greek\">θεός</span>): <span class=\"greek\">ὁ</span> <span class=\"greek\">υἱὸς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ἐξουσίαν</span> <span class=\"greek\">μεγάλην</span> <span class=\"greek\">κεῖται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κυριότητα</span>, o Filho de Deus apresenta-se revestido de grande autoridade e poder de governo, Hs 5, 6, 1 (<span class=\"greek\">κεῖμαι</span> 3c). <span class=\"greek\">κυριότητα</span> <span class=\"greek\">ἀθετεῖν</span>, rejeitar o senhorio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 8</a>, e <span class=\"greek\">κυριότητος</span> <span class=\"greek\">καταφρονεῖν</span>, desprezar o senhorio, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:10</a>, geralmente considerado dependente daquele, são frequentemente (Ritschl, Spitta, HvSoden, BWeiss, Kühl, Mayor, Windisch, Knopf, Vrede e outros.—FHauck deixa a escolha em aberto entre 2 e 3) entendidos como referência à glória do Senhor rejeitada ou desprezada pelos mestres dissidentes. Talvez se trate de emprego do abstrato pelo concreto, <span class=\"greek\">κυριότης</span> por <span class=\"greek\">κύριος</span>; veja o seguinte.</p>\n<p class=\"entry-text\">③ Classe especial de poderes angélicos, portadores de autoridade governante, dominações (compare En 61:10; Slav. En 20; TestSol 8:6 D e veja <span class=\"greek\">κύριος</span> II 2b<span class=\"greek\">ε</span><span class=\"hebrew\" dir=\"rtl\">ב</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:21</a>; AcPl Ha 1, 7 [restaurado].—GMacGregor, Principalities and Powers; the Cosmic Background of Paul’s Thought: NTS 1, ’54, 17–28. ADupont-Sommer, Jahrb. f. kleinasiat. Forschung 1, ’50, 210–18.—DELG s.v. <span class=\"greek\">κύριο</span>. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0213-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κυρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">κυρόω</span> (compare <span class=\"greek\">κῦρος</span>, <span class=\"greek\">τό</span>, ‘poder supremo’): 1º aoristo <span class=\"greek\">ἐκύρωσα</span>. Na passiva, futuro, 3ª pessoa do singular, <span class=\"greek\">κυρωθήσεται</span>, Lev 25:30; aoristo, 3ª pessoa do singular, <span class=\"greek\">ἐκυρώθη</span>, Gen 23:20; particípio perfeito <span class=\"greek\">κεκυρωμένος</span> (Aeschyl., Hdt. e outros; inscrições, papiros, LXX, EpArist, Joseph.).</p>\n<p class=\"entry-text\">① Conferir sanção a algo; confirmar, ratificar, validar, tornar juridicamente vinculante (Dio Chrys. 59 [76], 1; SIG 368, 25; 695, 68f <span class=\"greek\">τὸ</span> <span class=\"greek\">κεκυρωμένον</span> <span class=\"greek\">ψήφισμα</span>; OGI 383, 122; Michel 478, 6; outras inscrições em New Docs 4, 171; PAmh 97, 14; 17; PTebt 294, 16; EpArist 26; veja OEger, ZNW 18, 1918, 88ff): <span class=\"greek\">κεκυρωμένην</span> <span class=\"greek\">διαθήκην</span> <span class=\"greek\">ἀθετεῖν</span>, anular testamento que foi ratificado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:15</a>.</p>\n<p class=\"entry-text\">② Chegar a uma decisão mediante processo cognitivo; concluir, decidir em favor de (Hdt. 6, 86, 8; 6, 126; Thu. 8, 69, 1; Jos., Bell. 4, 362, Ant. 2, 18): <span class=\"greek\">κ</span>. <span class=\"greek\">εἴς</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἀγάπην</span>, decidir a favor do amor por alguém, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 2:8</a> (embora talvez a ativa possa ter o mesmo sentido que a média em Pla., Gorg. 451b, isto é, tornar válido, afirmar; na passagem de 2 Cor, também merece consideração reafirmar [como NRSV]).—DELG s.v. <span class=\"greek\">κύριος</span>. M-M. TW.</p></section></article>"};
